#!/usr/bin/env python3
"""Generate private b16 asm blocks for ECM stage1 (512-bit add-mod)."""

from pathlib import Path

from mp_asm_block_gen import emit_add_block, emit_c_fix_add

ROOT = Path(__file__).resolve().parents[2]
OUT_ADD = ROOT / "kernels/opencl/add_mod/asm_512b.cl"
OUT_SUB = ROOT / "kernels/opencl/sub_mod/asm_512b.cl"


def main() -> None:
    asm_body = [
        "// AUTO-GENERATED by tools/gen_mp_addsub_asm_block16_stage1.py - do not edit.\n",
        "#if defined(__AMDGCN__)\n\n",
        emit_c_fix_add(16),
        emit_add_block(16, global_addr=False, fix_in_block=True),
        "#endif\n\n",
        "#if defined(__AMDGCN__)\n",
        "static inline void mp_add_mod_asm_b16_512(uint *r, const uint *a, const uint *b, const uint *N) {\n",
        "    uint ca = 0u, cs = 1u;\n",
        "    asm_fused_block16_priv(a, b, N, r, ca, cs, &ca, &cs);\n",
        "}\n",
        "#endif\n",
    ]
    OUT_ADD.write_text(
        "".join(asm_body)
        + (
            "\nstatic inline void ecm_stage1_add_mod(uint *r, const uint *a, const uint *b,\n"
            "                                        const uint *N, uint limbs) {\n"
            "#if defined(__AMDGCN__)\n"
            "    if (limbs == 16u) { mp_add_mod_asm_b16_512(r, a, b, N); return; }\n"
            "#else\n"
            "    if (limbs == 16u) { mp_add_mod_fused_unroll_b16_512(r, a, b, N); return; }\n"
            "#endif\n"
            "    (void)limbs;\n"
            "}\n"
        ),
        encoding="utf-8",
    )
    OUT_SUB.write_text(
        "".join(asm_body)
        + (
            "\nstatic inline int ecm_stage1_sub_mod(uint *r, const uint *a, const uint *b,\n"
            "                                       const uint *N, uint limbs) {\n"
            "    if (limbs == 16u) { return mp_sub_mod_fused_unroll_b16_512(r, a, b, N); }\n"
            "    return 0;\n"
            "}\n"
        ),
        encoding="utf-8",
    )
    print(f"Wrote {OUT_ADD}")
    print(f"Wrote {OUT_SUB}")


if __name__ == "__main__":
    main()
